mapper.select:
SELECT approve_status AS tabFlag, count(*) AS count FROM sku_std_cost_detail WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY approve_status

SELECT sscd.id AS id, -- 列表id sscd.sku_id AS skuId, -- skuId sscd.sku_no AS skuNo, -- sku编号 pd.name AS skuName, -- sku名称（此处主表无字段，可后续关联SKU基础信息表） sscd.is_comb AS isComb, -- 是否组合装 ps.sale_state AS saleState, -- 销售状态（此处主表无字段，可后续关联销售状态表） sscd.last_outstock_date AS lastOutstockDate, -- 最新出库时间 sscd.create_time AS createTime, -- 创建时间 sscd.create_user_name AS createUserName, -- 创建人名称 sscd.update_time AS updateTime, -- 更新时间 sscd.update_user_name AS updateUserName, -- 更新人名称 sscd.approve_status AS approveStatus, -- 审核状态 sscd.std_cost_price AS stdCostPrice, -- 标准成本(不含税) sscd.currency AS currency, -- 币别 sscd.effective_date AS effectiveDate, -- 生效日期 sscd.expire_date AS expireDate, -- 失效日期 sscd.approve_user_id AS approveUserId, -- 审核人ID sscd.approve_user_name AS approveUserName, -- 审核人名称 sscd.approve_time AS approveTime -- 审核时间 FROM sku_std_cost_detail as sscd LEFT JOIN sku_std_cost as ssc on sscd.main_id = ssc.id LEFT JOIN product_detail as pd on pd.id = ssc.sku_id LEFT JOIN product_sale as ps on psscd.sku_id = ssc.sku_id; WHERE ${params.sqlMap.default} and sscd.is_deleted = false and ssc.is_deleted = false and pd.i.is_deleted = false and ps.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sscd.update_time desc
